refentry.refsect1:
  &reftitle.examples;



    Esempio di clearstatcache


<?php

$file = tempnam(sys_get_temp_dir(), 'stat-demo-');
file_put_contents($file, 'Ciao');

echo "Eseguire questo comando in un'altra shell:\n";
echo "\techo \" Mondo!\" >> $file\n";

$before = filesize($file); // memorizza in cache i metadati

sleep(20); // Eseguire il comando echo in un'altra shell

$cached = filesize($file); // vengono restituiti dati non aggiornati

clearstatcache();

$fresh = filesize($file);  // restituisce i dati corretti

printf("Prima: %d\nIn cache: %d\nAggiornato: %d\n", $before, $cached, $fresh);

unlink($file);


    &example.outputs.similar;


Eseguire questo comando in un'altra shell:
    echo " Mondo!" >> /tmp/stat-demo-6fjvs4vir9ll2haCl4W
Prima: 4
In cache: 4
Aggiornato: 12
